import {validateHistory} from '../../E024-transitions/code/transitions.mjs';
import {collectPanel} from './panel.mjs';
import {verifyPanel} from './verify-panel.mjs';
import {derive} from './derive.mjs';
import {explainMove as parent,priority as inherited} from '../../E149-minority-structure/code/minority.mjs';
export const priority=e=>e.evidence?.experiment==='E150'?187.85:inherited(e);
export function explainMove(input){const enabled=input.advantageResourceTags===undefined?false:input.advantageResourceTags;if(typeof enabled!=='boolean')throw Error('advantageResourceTags must be boolean');if(!enabled)return parent(input);const limit=input.maxAdvantageResourceNodes===undefined?50000:input.maxAdvantageResourceNodes;if(!Number.isSafeInteger(limit)||limit<0||limit>50000)throw Error('maxAdvantageResourceNodes must be integer0..50000');const base=parent(input);let nodes=0,witness=null,events=base.events,status='history-prerequisite';const done=()=>({...base,schema:'coach-concepts-E150-prototype',events,comment:events===base.events?base.comment:[...events].sort((a,b)=>priority(b)-priority(a))[0]?.text||null,advantageResourceAnalysis:{limit,nodes,status,witness}});if(base.error||base.foundationAnalysis&&base.foundationAnalysis.status!=='accepted'){status='not-applicable';return done();}
  try{if(!limit)throw Error('advantage-resource-budget');nodes=1;const h=validateHistory(input);if(!h)return done();if(limit<6+h.moves.length)throw Error('advantage-resource-budget');const p=input.advantageResourcePanel===undefined?collectPanel(input,limit-3):input.advantageResourcePanel;if(!p||typeof p!=='object')throw Error('Expected advantage resource panel');if(3+p.nodes>limit)throw Error('advantage-resource-budget');nodes=3+verifyPanel(input,p).nodes;witness=derive(input,p);if(witness.after!==base.after)throw Error('Parent resource endpoint differs');if(p.claimContexts.length){status='claim-rule-prerequisite';return done();}const extra=[],add=(id,text)=>{if(text.split(/\s+/).length>24)throw Error('Comment exceeds24words');extra.push({id,text,qualityClaim:false,evidence:{experiment:'E150',before:witness.before,after:witness.after,detail:{source:'advantageResourceAnalysis.witness'}}});};
    if(witness.staticEdge)add('bounded-static-material-edge',`Static material edge: a quiet policy retains at least ${witness.staticEdge.minimum} nominal points of existing lead across two opponent turns. Longer durability remains unproved.`);
    if(witness.dynamicEdge)add('temporary-checking-piece-resource',`Dynamic resource: this checking fork forces at least ${witness.dynamicEdge.minimumGain} nominal points through immediate counterreplies; ${input.advantageAlternative} lacks that bounded same-piece resource. Deeper outcomes remain open.`);
    if(extra.length){events=[...base.events,...extra];status='proven';}else status='compared';
  }catch(e){if(e.message!=='advantage-resource-budget')throw e;nodes=limit+1;events=base.events;witness=null;status='exhausted';}return done();}
